$('open').onclick = () => $('file').click();
$('file').onchange = (e) => { readFile(e.target.files[0]); e.target.value = ''; };
let dragDepth = 0;
window.addEventListener('dragenter', (e) => { e.preventDefault(); dragDepth++; $('veil').hidden = false; });
window.addEventListener('dragleave', (e) => { dragDepth = Math.max(0, dragDepth-1); if(!dragDepth) $('veil').hidden = true; });
window.addEventListener('dragover', (e) => e.preventDefault());
window.addEventListener('drop', (e) => { e.preventDefault(); dragDepth = 0; $('veil').hidden = true; readFile(e.dataTransfer.files[0]); });

// ---------- settings ----------
document.querySelectorAll('[data-prec]').forEach(b => b.onclick = () => {
  document.querySelectorAll('[data-prec]').forEach(x => x.setAttribute('aria-pressed', x === b));
  state.prec = parseFloat(b.dataset.prec); $('tol').value = ''; state.keepView = true; run();
});
$('units').onchange = () => { state.unitAuto = false; state.keepView = true; run(); };
let deb;
['tol','ang','tCyl','tCone','tSph','tTor','facet'].forEach(id => $(id).addEventListener('change', () => { clearTimeout(deb); deb = setTimeout(() => { state.keepView = true; run(); }, 150); }));
$('rerun').onclick = () => { state.keepView = true; run(); };

